    override suspend fun findByLogin(login: String): User? = withContext(Dispatchers.IO) {
        ds.connection.use { c ->
            c.prepareStatement("select id, login, password_hash from users where login = ?").use { ps ->
                ps.setString(1, login)
                ps.executeQuery().use { rs ->
                    if (rs.next()) User(rs.getString("id"), rs.getString("login"), rs.getString("password_hash"))
                    else null
                }
            }
        }
    }
}

// Ktor: провайдер аутентификации + JWT
install(Authentication) {
    jwt("auth-jwt") {
        verifier(JwtVerifier(...))
        validate { cred -> cred.payload.getClaim("uid").asString()?.let { JWTPrincipal(cred.payload) } }
    }
}

// маршрут логина (без Spring)
post("/login") {
    val req = call.receive<LoginRequest>()
    val user = users.findByLogin(req.login)
    if (user == null || !PasswordHasher.verify(req.password, user.passwordHash))
        call.respond(HttpStatusCode.Unauthorized) else
        call.respond(LoginResponse(tokens.issue(user.id)))
}
