                .filter(u -> encoder.matches(c.password(), u.passwordHash()))
                .map(u -> ResponseEntity.ok(Map.of("token", jwt.generate(u.username(), u.roles()))))
                .orElseGet(() -> ResponseEntity.status(401).body(Map.of("error", "invalid credentials")));
