    }

    @PostMapping("/register")
    public ResponseEntity<?> register(@RequestBody AuthRequest req) {
        userService.register(req.username(), req.password());
        return ResponseEntity.ok("registered");
    }

    @GetMapping("/me")
    public String me(Authentication auth) {
